// Test client for the isolated :3001 instance. Never prints the password.
// usage: node client.mjs <cmd> [args]
//   caps-get | caps-put <usd> <tokens> | caps-delete | clear | history
//   ask "<text>" | decide <escalationId> <approve|deny> | raw-ask "<text>"
import { readFileSync, writeFileSync } from "node:fs";

const BASE = process.env.BASE ?? "http://localhost:3001";
const AGENT = process.env.AGENT ?? "assistant";
const USER = process.env.TEST_USER ?? "adminuser1";
const SCRATCH = new URL(".", import.meta.url).pathname;
const COOKIE_FILE = `${SCRATCH}cookie-${USER}.txt`;

async function cookie() {
  try {
    return readFileSync(COOKIE_FILE, "utf8");
  } catch {}
  const seed = JSON.parse(readFileSync("/Users/apple/Open/nlhack/seed-users.json", "utf8"));
  const users = Array.isArray(seed) ? seed : seed.users;
  const u = users.find((x) => x.username === USER);
  const res = await fetch(`${BASE}/api/auth/sign-in/username`, {
    method: "POST",
    headers: { "content-type": "application/json", origin: BASE },
    body: JSON.stringify({ username: u.username, password: u.password }),
  });
  if (!res.ok) throw new Error(`sign-in ${res.status} ${await res.text()}`);
  const c = res.headers.getSetCookie().map((x) => x.split(";")[0]).join("; ");
  writeFileSync(COOKIE_FILE, c);
  return c;
}

async function api(path, init = {}) {
  const res = await fetch(`${BASE}${path}`, { ...init, headers: { cookie: await cookie(), "content-type": "application/json", origin: BASE, ...(init.headers ?? {}) } });
  return res;
}

async function chat(message) {
  const t0 = Date.now();
  const res = await api(`/api/chat/${AGENT}`, { method: "POST", body: JSON.stringify({ message }) });
  if (!res.ok) {
    console.log("HTTP", res.status, await res.text());
    return;
  }
  const raw = await res.text();
  const parts = raw.split("\n").filter((l) => l.startsWith("data: ") && l !== "data: [DONE]").map((l) => JSON.parse(l.slice(6)));
  let text = "";
  const tools = [];
  let usage;
  for (const p of parts) {
    if (p.type === "text-delta") text += p.delta;
    if (p.type === "tool-input-available") tools.push({ id: p.toolCallId, name: p.toolName, input: p.input });
    if (p.type === "tool-output-available" || p.type === "tool-output-error") {
      const t = tools.find((x) => x.id === p.toolCallId);
      if (t) t.out = p.type === "tool-output-error" ? `ERROR ${p.errorText}` : JSON.stringify(p.output).length + " chars";
    }
    if (p.type === "data-turn-usage") usage = p.data;
    if (p.type === "error") console.log("STREAM ERROR", p.errorText);
  }
  writeFileSync(`${SCRATCH}last-stream.json`, JSON.stringify(parts, null, 1));
  console.log(`--- ${((Date.now() - t0) / 1000).toFixed(1)}s, ${parts.length} parts`);
  console.log("TOOLS", JSON.stringify(tools.map((t) => ({ name: t.name, input: t.input, out: t.out }))));
  console.log("TEXT\n" + text);
  console.log("USAGE", JSON.stringify(usage));
}

const [cmd, ...args] = process.argv.slice(2);
const id = () => `test-${Date.now()}`;
if (cmd === "caps-get") console.log(await (await api(`/api/agents/${AGENT}/caps`)).text());
else if (cmd === "caps-put")
  console.log(await (await api(`/api/agents/${AGENT}/caps`, { method: "PUT", body: JSON.stringify({ costCapUsd: Number(args[0]), tokenCap: Number(args[1]) }) })).text());
else if (cmd === "caps-delete") console.log(await (await api(`/api/agents/${AGENT}/caps`, { method: "DELETE" })).text());
else if (cmd === "clear") console.log((await api(`/api/chat/${AGENT}/history`, { method: "DELETE" })).status);
else if (cmd === "history") {
  const h = await (await api(`/api/chat/${AGENT}/history`)).json();
  writeFileSync(`${SCRATCH}history.json`, JSON.stringify(h, null, 1));
  for (const m of h.messages) {
    console.log(`== ${m.role} ${m.id} meta=${JSON.stringify(m.metadata ?? {}).slice(0, 400)}`);
    for (const p of m.parts) {
      if (p.type === "text") console.log("  text:", p.text.slice(0, 300).replace(/\n/g, " "));
      else if (p.type.startsWith("tool-") || p.type === "dynamic-tool")
        console.log("  ", p.type, p.state, JSON.stringify(p.input).slice(0, 120), "->", p.output !== undefined ? JSON.stringify(p.output).length + " chars" : p.errorText);
      else console.log("  ", p.type);
    }
  }
} else if (cmd === "ask") await chat({ id: id(), role: "user", parts: [{ type: "text", text: args[0] }] });
else if (cmd === "decide")
  await chat({ id: id(), role: "user", parts: [{ type: "text", text: args[1] }], metadata: { capEscalation: { id: args[0], approved: args[1] === "approve" } } });
else console.log("unknown cmd");

// Bubble markup ported from rakazo's Transcript/MessageView (apps/web/src/pages/Shell.tsx
// ~5092-5112 and ~6847-6880), Apache-2.0, github.com/elie222/rakazo@912c977.
import type { UIMessage } from "ai";
import { Check, ChevronRight, OctagonAlert, RotateCcw, ShieldAlert, X } from "lucide-react";
import * as m from "motion/react-m";
import { type ReactNode, useState } from "react";
import { StandaloneToolActivity } from "@/components/chat/ToolActivityDisclosure";
import { Button } from "@/components/ui/button";
import { Collapse } from "@/components/motion/Collapse";
import { DURATION, enterTransition, exitTransition } from "@/lib/motion";
import { ChatMarkdown, LinkifiedText } from "@/components/markdown/markdown.web";
import { type AgentNames, messageSegments, messageText, toolsDurationMs } from "@/lib/message-parts";
import { toolStepCount } from "@/lib/tool-activity-view";
import {
  capNoticeText,
  type EscalationOffer,
  escalationText,
  messageEscalationDecision,
  messageTurnUsage,
  type TurnUsage,
} from "@/lib/turn-usage";

const USER_WIDTH = "max-w-[min(84%,calc(100%_-_8rem))] max-md:max-w-[84%] [@media(hover:none)]:max-w-[84%]";
const BOT_WIDTH = "max-w-[min(88%,calc(100%_-_8rem))] max-md:max-w-[92%] [@media(hover:none)]:max-w-[88%]";

function Row({ user, children }: { user: boolean; children: ReactNode }) {
  return (
    <div className={`relative flex ${user ? "justify-end" : "justify-start"}`}>
      <div className={`relative w-fit min-w-0 ${user ? USER_WIDTH : BOT_WIDTH}`}>{children}</div>
    </div>
  );
}

export function MessageBubble({
  message,
  streaming,
  earlier,
  agentNames,
  onApproval,
  next,
  onEscalation,
}: {
  message: UIMessage;
  /** This is the assistant message currently being streamed. */
  streaming: boolean;
  /** A later message follows this one, so nothing in it is still in progress. */
  earlier: boolean;
  agentNames: AgentNames;
  /** Answers a tool call awaiting approval; omitted when this message can't be answered now. */
  onApproval?: (approvalId: string, approved: boolean) => void;
  /** The message after this one, if any (it tells whether a capped reply's escalation was decided). */
  next?: UIMessage;
  /** Approves or denies this reply's budget extension; omitted when it can't be decided now. */
  onEscalation?: (escalationId: string, approved: boolean) => void;
}) {
  if (message.role === "user") {
    // An Approve/Deny on an escalation card is sent as a user message; the card already shows it.
    if (messageEscalationDecision(message)) return null;
    const text = messageText(message);
    if (!text) return null;
    return (
      <Row user>
        <div
          data-testid="message-user-bubble"
          className="max-w-full whitespace-pre-wrap wrap-anywhere rounded-[20px] bg-chat-user px-[18px] py-3 text-[15.5px] leading-[1.45] text-chat-user-foreground"
          dir="auto"
        >
          <LinkifiedText>{text}</LinkifiedText>
        </div>
      </Row>
    );
  }

  const segments = messageSegments(message, agentNames);
  const usage = messageTurnUsage(message);
  return (
    <div className="relative flex flex-col gap-1.5">
      {segments.map((segment, index) => {
        const last = index === segments.length - 1;
        if (segment.kind === "tools") {
          const live = streaming && segment.steps.some((step) => step.status === "running");
          // In an earlier reply a call can't still be running: it never ran (an approval dropped
          // when the user sent a new message), so it shows as declined.
          const steps = earlier
            ? segment.steps.map((step) => (step.status === "running" ? { ...step, status: "denied" as const } : step))
            : segment.steps;
          return (
            <StandaloneToolActivity
              key={segment.key}
              live={live}
              steps={steps}
              stepCount={toolStepCount(steps)}
              durationMs={live ? undefined : toolsDurationMs(segment.callIds)}
            />
          );
        }
        if (segment.kind === "approval") {
          return (
            <ApprovalCard
              key={segment.key}
              label={segment.label}
              agent={segment.agent}
              toolName={segment.toolName}
              input={segment.input}
              onRespond={onApproval ? (approved) => onApproval(segment.approvalId, approved) : undefined}
            />
          );
        }
        if (segment.kind === "reasoning") {
          return <ReasoningNote key={segment.key} text={segment.text} />;
        }
        return (
          <Row key={segment.key} user={false}>
            <div
              data-testid="message-bot-bubble"
              className="max-w-full rounded-[20px] bg-muted px-[18px] py-3 text-[15.5px] leading-[1.5] text-foreground/90"
              dir="auto"
            >
              <ChatMarkdown streaming={streaming && last}>{segment.text}</ChatMarkdown>
            </div>
          </Row>
        );
      })}
      {usage?.capped ? (
        usage.escalation ? (
          <EscalationCard
            usage={usage}
            offer={usage.escalation}
            outcome={escalationOutcome(usage.escalation, next)}
            onRespond={onEscalation ? (approved) => onEscalation(usage.escalation!.id, approved) : undefined}
          />
        ) : (
          <CapNotice text={capNoticeText(usage)} />
        )
      ) : null}
      {usage?.continuation?.decision === "denied" ? (
        <CapNotice text="Incomplete: answered from what was gathered before the limit, since more budget was declined." />
      ) : null}
    </div>
  );
}

type EscalationOutcome = "approved" | "denied" | "dropped";

/** Decided when the next message is the decision (live), or as the server last saved it (reload). */
function escalationOutcome(offer: EscalationOffer, next: UIMessage | undefined): EscalationOutcome | undefined {
  if (next) {
    const decision = messageEscalationDecision(next);
    return decision && decision.id === offer.id ? (decision.approved ? "approved" : "denied") : "dropped";
  }
  return offer.status === "pending" ? undefined : offer.status;
}

const ESCALATION_OUTCOME_TEXT: Record<EscalationOutcome, string> = {
  approved: "Approved: finished below with a one-time extension.",
  denied: "Denied: answered below from what was gathered.",
  dropped: "Not continued: no decision was made.",
};

/**
 * End of a capped reply: what it spent and an offer to finish it with a one-time extension (the
 * user's limit stays as it is). Same look as a tool approval card.
 */
function EscalationCard({
  usage,
  offer,
  outcome,
  onRespond,
}: {
  usage: TurnUsage;
  offer: EscalationOffer;
  outcome?: EscalationOutcome;
  onRespond?: (approved: boolean) => void;
}) {
  const title = escalationText(usage, offer);
  const pending = !outcome && onRespond;
  return (
    <Row user={false}>
      <div
        role="group"
        aria-label={title}
        data-testid="turn-cap-escalation"
        className="flex max-w-full flex-col gap-2 rounded-[20px] border border-border bg-muted/60 px-[18px] py-3 text-[14.5px] leading-[1.45] text-foreground/90"
      >
        <div className="flex items-start gap-2 font-medium">
          <OctagonAlert size={15} strokeWidth={1.8} className="mt-[3px] shrink-0 text-destructive" />
          <span className="min-w-0 break-words">{title}</span>
        </div>
        {pending ? (
          <>
            <div className="text-[13px] text-muted-foreground">
              Approve to finish this reply with a one-time extension; your limit stays as it is. Deny to get the best
              answer from what was gathered. Or raise the limit from the bot name ▾.
            </div>
            <div className="flex gap-2">
              <Button size="sm" onClick={() => onRespond(true)}>
                <Check strokeWidth={1.8} />
                Approve
              </Button>
              <Button size="sm" variant="outline" onClick={() => onRespond(false)}>
                <X strokeWidth={1.8} />
                Deny
              </Button>
            </div>
          </>
        ) : (
          <div className="text-[13px] text-muted-foreground">
            {outcome ? ESCALATION_OUTCOME_TEXT[outcome] : "Raise the limit from the bot name ▾."}
          </div>
        )}
      </div>
    </Row>
  );
}

/** End-of-reply notice when the turn hit the user's cost or token cap for this agent. */
function CapNotice({ text }: { text: string }) {
  return (
    <Row user={false}>
      <div
        role="note"
        data-testid="turn-cap-notice"
        className="flex max-w-full items-start gap-2 rounded-[16px] border border-destructive/35 bg-destructive/8 px-3.5 py-2 text-[13.5px] leading-[1.45] text-foreground/85"
      >
        <OctagonAlert size={15} strokeWidth={1.8} className="mt-[2px] shrink-0 text-destructive" />
        <span className="min-w-0 break-words">{text}</span>
      </div>
    </Row>
  );
}

import type { UIMessage, UIMessageChunk } from "ai";
import type { TurnCaps } from "./usage/caps";
import type { TurnUsage } from "./usage/turn-budget";

/**
 * "Cap then escalate": a turn stopped by its cap offers a one-time budget extension instead of
 * dead-ending. The offer is saved on the capped reply as `metadata.capEscalation` (state lives on
 * the server; the client only ever sends `{ id, approved }`). Approve runs a continuation turn with
 * the granted budget; Deny runs one tool-less model step that answers from what was gathered.
 */
export type CapEscalationStatus = "pending" | "approved" | "denied" | "dropped";

/** What the client sees of an offer (on `TurnUsage.escalation`, streamed and saved). */
export type EscalationOffer = { id: string; extraCostUsd: number; extraTokens: number; status: CapEscalationStatus };

/** The server-side record on the capped reply. `id` is the capped turn's trace id. */
export type CapEscalation = EscalationOffer & {
  traceId: string;
  question: string;
  findings: string;
};

export type EscalationDecision = { id: string; approved: boolean };

/** Set on a continuation turn's usage, so the client can label it and the capped reply's card. */
export type Continuation = { from: string; decision: "approved" | "denied" };

/**
 * The one-time extension offered for finishing: 1.5 × whichever is larger, the cap or what the
 * turn actually spent. The capped run is unfinished and we cannot know how many steps remain, so
 * "about as much again as it took to get here" is the simplest honest guess; the extra half covers
 * the final synthesis step, which carries the largest context. Rounded up to the cent / 1k tokens.
 */
export function estimateExtension(usage: Pick<TurnUsage, "costUsd" | "tokens" | "capCostUsd" | "capTokens">): TurnCaps {
  const cost = 1.5 * Math.max(usage.capCostUsd, usage.costUsd);
  const tokens = 1.5 * Math.max(usage.capTokens, usage.tokens);
  return { costCapUsd: Math.ceil(cost * 100) / 100, tokenCap: Math.ceil(tokens / 1000) * 1000 };
}

/**
 * Budget for a Deny answer. It runs as a single model step with no tools (maxSteps 1, toolChoice
 * "none"), so its cost is bounded by one call over the context already gathered; the cap is only
 * a backstop and half of the user's own cap is ample for that one step. If it still tripped, the
 * TripWire would drop the answer, which is why it is not made smaller.
 */
export function denyBudget(caps: TurnCaps): TurnCaps {
  return { costCapUsd: caps.costCapUsd / 2, tokenCap: Math.max(1, Math.floor(caps.tokenCap / 2)) };
}

/** A client message carrying a decision: a user message whose metadata is `{ capEscalation: { id, approved } }`. */
export function escalationDecision(message: UIMessage): EscalationDecision | undefined {
  if (message.role !== "user") return undefined;
  const value = (message.metadata as { capEscalation?: unknown } | undefined)?.capEscalation;
  if (!value || typeof value !== "object") return undefined;
  const { id, approved } = value as { id?: unknown; approved?: unknown };
  return typeof id === "string" && id && typeof approved === "boolean" ? { id, approved } : undefined;
}

/** A stored message, narrowed to what is read here. */
type StoredMessage = { id: string; role: string; content: { metadata?: Record<string, unknown> } };

export function isCapEscalation(value: unknown): value is CapEscalation {
  if (!value || typeof value !== "object") return false;
  const e = value as Partial<CapEscalation>;
  return typeof e.id === "string" && typeof e.status === "string" && typeof e.extraCostUsd === "number" && typeof e.extraTokens === "number";
}

/**
 * The escalation still awaiting a decision: only on the newest assistant message (anything later
 * means the user moved on), and only while pending.
 */
export function pendingEscalation<M extends StoredMessage>(messages: readonly M[]): { message: M; escalation: CapEscalation } | undefined {
  const message = [...messages].reverse().find((m) => m.role === "assistant");
  const escalation = message?.content.metadata?.capEscalation;
  return message && isCapEscalation(escalation) && escalation.status === "pending" ? { message, escalation } : undefined;
}

/**
 * The stored replies whose escalation is still pending, with it marked `status` (the escalation is
 * also mirrored on `turnUsage.escalation`, which the client reads, so both are updated).
 */
export function withEscalationStatus<M extends StoredMessage>(messages: readonly M[], status: CapEscalationStatus, id?: string): Pick<M, "id" | "content">[] {
  const updated: Pick<M, "id" | "content">[] = [];
  for (const message of messages) {
    const metadata = message.content.metadata;
    const escalation = metadata?.capEscalation;
    if (message.role !== "assistant" || !isCapEscalation(escalation) || escalation.status !== "pending") continue;
    if (id && escalation.id !== id) continue;
    const usage = metadata?.turnUsage as (TurnUsage & { escalation?: EscalationOffer }) | undefined;
    updated.push({
      id: message.id,
      content: {
        ...message.content,
        metadata: {
          ...metadata,
          capEscalation: { ...escalation, status },
          ...(usage?.escalation ? { turnUsage: { ...usage, escalation: { ...usage.escalation, status } } } : {}),
        },
      },
    });
  }
  return updated;
}

/** Hidden prompt for the continuation turn, built on the server (client text is ignored). */
export function continuationPrompt(escalation: CapEscalation, approved: boolean): string {
  const findings = escalation.findings || "(Nothing was gathered before the stop.)";
  if (approved) {
    return [
      `[Budget extension approved: about $${escalation.extraCostUsd.toFixed(2)} more for this reply only.]`,
      "Your previous reply to the request below stopped at its cost limit before finishing. Finish it now.",
      "Reuse the findings gathered so far (below) as they are: do not re-read files or re-ask specialists whose results are listed. Only delegate work that is marked as not done, and only if the answer needs it. Then give the complete answer.",
      `Original request:\n${escalation.question}`,
      `Findings gathered so far:\n${findings}`,
    ].join("\n\n");
  }
  return [
    "[Budget extension declined.]",
    "Your previous reply to the request below stopped at its cost limit before finishing, and the user declined more budget.",
    "Without calling any tools or specialists, give the best answer you can from the findings below. Start with the line \"Incomplete answer (budget extension declined):\", and say briefly what is missing.",
    `Original request:\n${escalation.question}`,
    `Findings gathered so far:\n${findings}`,
  ].join("\n\n");
}

const MAX_FINDING_CHARS = 6_000;
const MAX_FINDINGS_CHARS = 24_000;

type ToolCall = { name: string; input: unknown; output?: unknown; error?: string };

/**
 * Collects what a turn gathered from its UI stream, for the continuation prompt. Needed because a
 * TripWire abort stores nothing of the turn in the agent's own thread (measured: no user message,
 * no tool results); delegated sub-agents keep their answers only in their own threads.
 */
export class TurnFindings {
  private text = "";
  private readonly calls = new Map<string, ToolCall>();
  private readonly order: string[] = [];

  add(part: UIMessageChunk): void {
    if (part.type === "text-delta") this.text += part.delta;
    else if (part.type === "tool-input-available") {
      if (!this.calls.has(part.toolCallId)) this.order.push(part.toolCallId);
      this.calls.set(part.toolCallId, { name: part.toolName, input: part.input });
    } else if (part.type === "tool-output-available") {
      const call = this.calls.get(part.toolCallId);
      if (call) call.output = part.output;
    } else if (part.type === "tool-output-error") {
      const call = this.calls.get(part.toolCallId);
      if (call) call.error = part.errorText;
    }
  }

  /** The assistant text streamed so far (without the server's cap note). */
  get partialText(): string {
    return this.text;
  }

  /**
   * A compact digest: each specialist's answer (or that it never ran), and the files already read.
   * File contents are left out: the specialists' answers carry what they found, and the list stops
   * the model from re-reading them.
   */
  digest(): string {
    const lines: string[] = [];
    const files: string[] = [];
    let budget = MAX_FINDINGS_CHARS;
    for (const id of this.order) {
      const call = this.calls.get(id)!;
      if (call.name.startsWith("agent-")) {
        const specialist = call.name.slice("agent-".length);
        const text = (call.output as { text?: unknown } | undefined)?.text;
        if (typeof text === "string" && text.trim()) {
          const clipped = clip(text.trim(), Math.min(MAX_FINDING_CHARS, budget));
          budget -= clipped.length;
          lines.push(`### ${specialist} (done)\n${clipped}`);
        } else {
          const ask = (call.input as { prompt?: unknown } | undefined)?.prompt;
          lines.push(`### ${specialist} (NOT done: stopped before it answered)${typeof ask === "string" ? `\nTask it was given: ${clip(ask, 600)}` : ""}`);
        }
      } else if (call.name === "company_read_file") {
        const path = (call.input as { path?: unknown } | undefined)?.path;
        if (typeof path === "string") files.push(path);
      }
    }
    if (files.length) lines.push(`### Files already read by you\n${[...new Set(files)].join(", ")}`);
    if (this.text.trim()) lines.push(`### Your partial reply\n${clip(this.text.trim(), 2_000)}`);
    return lines.join("\n\n");
  }
}

function clip(text: string, max: number): string {
  return text.length <= max ? text : `${text.slice(0, Math.max(0, max - 20))}\n…[truncated]`;
}

