import { readFileSync, writeFileSync } from "node:fs";
import assert from "node:assert/strict";

const load = name => JSON.parse(readFileSync(`/private/tmp/nlhack-browser-${name}-history.json`, "utf8"));
const approved = load("approve").messages.filter(m => m.role === "assistant");
const denied = load("deny").messages.filter(m => m.role === "assistant");
assert.equal(approved.at(-1).metadata.turnUsage.continuation.decision, "approved");
assert.equal(approved.at(-1).metadata.turnUsage.capped, false);
assert.equal(approved.at(-1).metadata.turnUsage.capCostUsd, 0.04);
assert.equal(denied[0].parts[0].text, "This reply stopped at its budget limit before an answer was ready.");
assert.equal(denied.at(-1).metadata.turnUsage.continuation.decision, "denied");
assert.equal(denied.at(-1).metadata.turnUsage.steps, 1);
assert.equal(denied.at(-1).parts.filter(p => p.type.startsWith("tool-") || p.type === "dynamic-tool").length, 0);
assert(denied.at(-1).parts.some(p => p.type === "text" && p.text.startsWith("Incomplete answer")));
const result = {
  checkedAt: new Date().toISOString(), instance: "http://localhost:3001 (copied databases)",
  browserChecks: ["Approve after reload completes with a one-time $0.04 budget", "Empty assistant output preserves fallback text and escalation after reload", "Deny on mobile produces one tool-free model step marked Incomplete", "Repeated decision returns HTTP 409", "Saved caps remain $0.02 during continuation; reset to defaults afterwards", "Usage panel shows actual continuation budget"],
  approved: approved.map(m => m.metadata.turnUsage),
  denied: denied.map(m => m.metadata.turnUsage),
  limitations: ["Answers are model-generated and contain documented factual/calculation errors; this verifies execution and core figures, not complete answer correctness."]
};
writeFileSync("/Users/apple/Open/nlhack/docs/demo/northwind-browser-verification.json", JSON.stringify(result,null,2)+"\n");
console.log("Browser history assertions passed.");

